import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md","lastUpdated":1778915731000}'),n={name:"guide/authentication.md"};function o(r,e,d,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Pika has two distinct authentication mechanisms:</p><ol><li><strong>Sessions</strong> for human users in the web UI (cookie-based).</li><li><strong>API tokens</strong> for programmatic consumers reading <code>/data/*</code> and <code>/raw/*</code>.</li></ol><p>In addition, pika can plug external identity providers in front of the session login: OAuth2/OIDC, LDAP, or a header-based forward-auth gateway.</p><h2 id="built-in-users" tabindex="-1">Built-in users <a class="header-anchor" href="#built-in-users" aria-label="Permalink to &quot;Built-in users&quot;">​</a></h2><p>Built-in session-based auth is always on. The first time you start the server, the UI shows a setup screen to create the initial admin account. After that, sign in and create more users from <strong>Settings → Users</strong>.</p><p>Each user belongs to one or more <strong>permission bundles</strong> that define which capabilities they hold. Bundles are managed under <strong>Settings → Permissions</strong>.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><p>Users (and externally-authenticated identities) are checked against pika&#39;s capability keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Grants</th></tr></thead><tbody><tr><td><code>files.read</code></td><td>View configurations, versions, variants, render, search, convert.</td></tr><tr><td><code>files.write</code></td><td>Create, update, delete configurations and variants.</td></tr><tr><td><code>raw.read</code></td><td>Browse and download raw mount contents.</td></tr><tr><td><code>raw.write</code></td><td>Upload, delete, rename, copy, move raw mount contents.</td></tr><tr><td><code>settings.manage</code></td><td>View and modify server settings, backup/restore, server encryption-key lifecycle.</td></tr><tr><td><code>tokens.manage</code></td><td>Create, edit, revoke API access tokens.</td></tr><tr><td><code>users.manage</code></td><td>Create, edit, delete, kick users (built-in auth only).</td></tr><tr><td><code>permissions.manage</code></td><td>Define permission bundles and assign them (built-in auth only).</td></tr></tbody></table><p>A bundle can also have an associated <strong>path pattern</strong> that scopes the file/raw permissions. For example, a bundle with <code>files.read</code> and pattern <code>team-a/**</code> lets the user read everything under <code>team-a/</code> but nothing else.</p><h2 id="api-tokens" tabindex="-1">API tokens <a class="header-anchor" href="#api-tokens" aria-label="Permalink to &quot;API tokens&quot;">​</a></h2><p>Tokens are the recommended way to authenticate non-human consumers. Mint them under <strong>Settings → Tokens</strong>.</p><p>A token has the format <code>pika_&lt;64hex&gt;</code> and one or more <strong>scopes</strong>. Each scope grants specific operations on a glob-matched path:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;operations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delete&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pass the token as a <code>Bearer</code> token:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer pika_...&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/data/myapp/config</span></span></code></pre></div><p>Token scope syntax and matching rules are documented in detail under <a href="/reference/tokens-and-scopes">Tokens &amp; scopes</a>.</p><h2 id="external-authentication" tabindex="-1">External authentication <a class="header-anchor" href="#external-authentication" aria-label="Permalink to &quot;External authentication&quot;">​</a></h2><p>Pika supports three external strategies, all configurable from <strong>Settings → Authentication</strong> at runtime:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>What it does</th></tr></thead><tbody><tr><td><strong>OAuth2 / OIDC</strong></td><td>Standard authorization-code flow with any compatible provider (Keycloak, Auth0, Okta, Azure AD, Google, …).</td></tr><tr><td><strong>LDAP</strong></td><td>Bind against an LDAP server. Optionally syncs users on a schedule.</td></tr><tr><td><strong>Forward-auth</strong></td><td>Trust headers set by an upstream gateway (Turna, Authelia, Authentik, oauth2-proxy, …). Pika sees <code>X-User</code>, etc.</td></tr></tbody></table><p>When any external strategy is enabled, pika uses a <strong>session-first</strong> approach:</p><ol><li>If the request has a valid local session cookie, the user is authenticated immediately.</li><li>If no session cookie is present, pika delegates to the configured external strategy.</li><li>If neither succeeds, the request gets a 401.</li></ol><p>Local login always works — even when external auth is on. The <code>/api/v1/info</code> endpoint is always public so the SPA can boot and show the login screen regardless of the external strategy&#39;s redirect behaviour.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Strategies are hot-swapped via an <a href="https://rakunlabs.github.io/ada/guide/runtime-reload.html" target="_blank" rel="noreferrer">ada Slot</a>. Toggling them on/off, changing the OIDC client secret, or adjusting LDAP filters does not require a restart.</p></div><h2 id="external-permissions" tabindex="-1">External permissions <a class="header-anchor" href="#external-permissions" aria-label="Permalink to &quot;External permissions&quot;">​</a></h2><p>Externally-authenticated users don&#39;t get rows in the local <code>users</code> table. By default they have <strong>no enforced permission checks</strong> — pika trusts the upstream IdP / gateway.</p><p>Enable enforcement under <strong>Settings → Authentication → Permissions</strong>, then map external groups (or OAuth2 scopes) to pika capabilities:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pika-editor  →  files.read, files.write, raw.read</span></span>
<span class="line"><span>auditors     →  files.read, raw.read, tokens.manage</span></span></code></pre></div><p>If your gateway emits <code>X-Groups: pika-editor,auditors</code> for a user, the user gets the <strong>union</strong> of both sets. Unknown groups are ignored. Users not in the Superadmins allowlist and without any matching group are denied any restricted action (403).</p><p>The header name and value separator are configurable. Pika also accepts repeated header lines as a single concatenated list. The same role/scope mapping applies to OAuth2 (token claims) and LDAP (group membership).</p><h2 id="user-sync-ldap" tabindex="-1">User sync (LDAP) <a class="header-anchor" href="#user-sync-ldap" aria-label="Permalink to &quot;User sync (LDAP)&quot;">​</a></h2><p>For LDAP, pika can periodically reconcile local user metadata against the directory:</p><ul><li>Browse the configured <code>UserBaseDN</code> with <code>UserFilter</code>.</li><li>For each entry, create-or-update a local user (idempotent).</li><li>Apply group → permission mappings from the source&#39;s <code>GroupPermissions</code>.</li><li>Reconcile missing users per the source&#39;s <code>OnMissing</code> policy (<code>disable</code> by default, or <code>ignore</code>).</li></ul><p>User sync is configured under <strong>Settings → Authentication → User sync</strong>. You can also trigger a one-shot run via:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/user-sync/run/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">source-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>…and inspect the last result with <code>GET /api/v1/user-sync/status</code>.</p>`,37)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
